package com.rishav.commerce.payment.messaging; import com.rishav.commerce.events.*; import com.rishav.commerce.payment.domain.*; import org.springframework.kafka.annotation.*; import org.springframework.kafka.core.*; import org.springframework.stereotype.*; import org.springframework.transaction.annotation.*; import java.time.*; import java.util.*;
@Component class PaymentProcessor {final PaymentRepository repo;final KafkaTemplate<String,Object> kafka; PaymentProcessor(PaymentRepository r,KafkaTemplate<String,Object> k){repo=r;kafka=k;} @KafkaListener(topics="inventory.reserved.v1",groupId="payment-service") @Transactional void pay(InventoryReservedEvent e){if(repo.existsById(e.orderId()))return; Payment p=repo.save(new Payment(e.orderId())); kafka.send("payments.completed.v1",e.orderId().toString(),new PaymentCompletedEvent(UUID.randomUUID(),e.orderId(),p.getPaymentId(),Instant.now()));}}
